const raw = $input.first().json.output || '';

function extractField(text, fieldName) {
  const re = new RegExp('"' + fieldName + '"\\s*:\\s*"((?:[^"\\\\]|\\\\[\\s\\S])*)"', 's');
  const match = text.match(re);
  if (match) return match[1]
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\');
  return null;
}

let post_title = extractField(raw, 'post_title');
let seo_title = extractField(raw, 'seo_title');
let meta_description = extractField(raw, 'meta_description');
let post_keywords = extractField(raw, 'post_keywords');
let intro_content = extractField(raw, 'intro_content');
let main_content = extractField(raw, 'main_content');
let faq_content = extractField(raw, 'faq_content');

// Fallback: JSON parse
if (!post_title || !main_content) {
  try {
    let cleaned = raw.trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();
    const s = cleaned.indexOf('{');
    const e = cleaned.lastIndexOf('}');
    if (s !== -1 && e !== -1) {
      const p = JSON.parse(cleaned.substring(s, e + 1));
      post_title = post_title || p.post_title;
      seo_title = seo_title || p.seo_title;
      meta_description = meta_description || p.meta_description;
      post_keywords = post_keywords || p.post_keywords;
      intro_content = intro_content || p.intro_content;
      main_content = main_content || p.main_content;
      faq_content = faq_content || p.faq_content;
    }
  } catch(e) {}
}

if (!post_title || !main_content) {
  throw new Error('Missing required fields: post_title or main_content not found in AI output.');
}

// Defaults
if (!seo_title) seo_title = post_title;
if (!meta_description) meta_description = post_keywords || post_title;
if (!intro_content) intro_content = '';
if (!faq_content) faq_content = '';

// FIX 1: Strip wrapping <p> tags from intro_content
intro_content = intro_content.replace(/^\s*<p>\s*/i, '').replace(/\s*<\/p>\s*$/i, '').trim();

// FIX 2: Convert markdown tables to styled HTML tables in main_content
function convertMarkdownTables(html) {
  return html.replace(/(?:^|\n)((?:\|.+\|\n?)+)/gm, function(match, tableBlock) {
    const lines = tableBlock.trim().split('\n').filter(l => l.trim());
    if (lines.length < 2) return match;
    const isSeparator = l => /^\|[-:\s|]+\|$/.test(l.trim());
    const parseRow = l => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
    const headerLine = lines[0];
    const sepLine = lines[1];
    if (!isSeparator(sepLine)) return match;
    const headers = parseRow(headerLine);
    const dataLines = lines.slice(2);
    let tableHtml = '<table style="width:100%;border-collapse:collapse;margin:20px 0;font-size:15px;">';
    tableHtml += '<thead><tr>';
    headers.forEach(h => {
      tableHtml += `<th style="background:#f2f2f2;border:1px solid #ccc;padding:10px 14px;text-align:left;font-weight:700;">${h}</th>`;
    });
    tableHtml += '</tr></thead><tbody>';
    dataLines.forEach((line, i) => {
      const cells = parseRow(line);
      const bg = i % 2 === 0 ? '#ffffff' : '#f9f9f9';
      tableHtml += `<tr style="background:${bg}">`;
      cells.forEach(c => {
        tableHtml += `<td style="border:1px solid #ccc;padding:10px 14px;">${c}</td>`;
      });
      tableHtml += '</tr>';
    });
    tableHtml += '</tbody></table>';
    return tableHtml;
  });
}
main_content = convertMarkdownTables(main_content);

// FIX 3: Convert <h3>Q: ...</h3> in faq_content to <p><strong>Q: ...</strong></p>
faq_content = faq_content.replace(/<h3>(.*?)<\/h3>/gi, '<p><strong>$1</strong></p>');

// FIX 4: Also handle <h4> just in case
faq_content = faq_content.replace(/<h4>(.*?)<\/h4>/gi, '<p><strong>$1</strong></p>');

// FIX 5: Prepend FAQ heading
if (faq_content && !faq_content.includes('<h2')) {
  faq_content = '<h2>Frequently Asked Questions</h2>' + faq_content;
}

return [{ json: { post_title, seo_title, meta_description, post_keywords, intro_content, main_content, faq_content } }];

