const raw = $input.first().json.output || '';

function extractJson(text) {
  let cleaned = text.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  if (s !== -1 && e !== -1) return JSON.parse(cleaned.substring(s, e + 1));
  throw new Error('Could not parse pins JSON from AI output');
}

const parsed = extractJson(raw);
const pins = parsed.pins || [];
if (!Array.isArray(pins) || pins.length < 1) throw new Error('No pins found in AI output');

const toolUrl = $('Get row(s) in sheet').item.json['Tool URL'] || '';
const link = 'https://www.shortconverter.com/' + toolUrl.replace(/^https?:\/\/[^\/]+\//, '');

return pins.slice(0, 3).map((p, i) => ({
  json: {
    pin_index: i + 1,
    heading: p.heading || '',
    title: (p.title || '').substring(0, 100),
    description: p.description || '',
    hashtags: p.hashtags || '',
    image_prompt: p.image_prompt || '',
    link
  }
}));

const imgItems = $input.all();
const pinItems = $('Parse Pinterest Pins').all();

const pins = imgItems.map((item, i) => {
  const src = (pinItems[i] && pinItems[i].json) ? pinItems[i].json : {};
  const mimeType = (item.binary && item.binary.data && item.binary.data.mimeType) ? item.binary.data.mimeType : 'image/png';
  return {
    title: src.title || '',
    description: (src.description || '') + (src.hashtags ? ('\n\n' + src.hashtags) : ''),
    hashtags: src.hashtags || '',
    link: src.link || '',
    content_type: (mimeType === 'image/jpg') ? 'image/jpeg' : mimeType,
    image_base64: item.json.image_base64
  };
});

return [{ json: { pin1: pins[0] || {}, pin2: pins[1] || {}, pin3: pins[2] || {} } }];
